package com.bank.health.broker;

import com.bank.health.model.Message;
import java.util.*;

// One partition: ordered messages with increasing offsets.
public class PartitionLog {
    private final int partitionId;
    private final List<Message> messages = new ArrayList<>();

    public PartitionLog(int partitionId) { this.partitionId = partitionId; }
    public void produce(Message m) { messages.add(m); }
    public int getPartitionId() { return partitionId; }
    public List<Message> getMessages() { return messages; }
    public long logEndOffset() { return messages.size(); } // newest offset
}
