package com.bank.health.consumer;

import com.bank.health.broker.PartitionLog;
import com.bank.health.model.Message;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Simulates a consumer group: assignment, lag, retries+DLQ, rebalance.
public class ConsumerGroup {
    private static final Logger log = Logger.getLogger(ConsumerGroup.class.getName());
    private final int maxRetries;
    private final List<Message> deadLetterQueue = new ArrayList<>();
    private final Map<Integer, Long> committed = new HashMap<>(); // partition → committed offset
    private List<String> consumers = new ArrayList<>();

    public ConsumerGroup(int maxRetries) { this.maxRetries = maxRetries; }

    public void addConsumer(String name, List<PartitionLog> partitions) {
        consumers.add(name);
        log.info("REBALANCE: consumer " + name + " joined; reassigning " + partitions.size()
                + " partitions across " + consumers.size() + " consumers");
    }

    public void poll(PartitionLog partition) {
        long start = committed.getOrDefault(partition.getPartitionId(), 0L);
        for (long off = start; off < partition.logEndOffset(); off++) {
            Message m = partition.getMessages().get((int) off);
            if (!process(m)) {
                deadLetterQueue.add(m);
                log.warning(() -> "DLQ: poison record at offset " + m.getOffset() + " diverted");
            }
            committed.put(partition.getPartitionId(), off + 1); // commit progress
        }
        long lag = partition.logEndOffset() - committed.get(partition.getPartitionId());
        log.info("Partition " + partition.getPartitionId() + " lag now = " + lag);
    }

    // Process with bounded retries; returns false if it stays poison.
    private boolean process(Message m) {
        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            if (m.getAmount() != null && m.getAmount().compareTo(BigDecimal.ZERO) > 0) {
                log.fine(() -> "processed offset " + m.getOffset() + " for " + m.getAccountId());
                return true;
            }
            final int a = attempt;
            log.warning(() -> "retry " + a + " failed for offset " + m.getOffset());
        }
        return false;
    }

    public int dlqSize() { return deadLetterQueue.size(); }
}
