package com.bank.health;

import com.bank.health.broker.PartitionLog;
import com.bank.health.consumer.ConsumerGroup;
import com.bank.health.model.Message;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class HealthDemo {
    private static final Logger log = Logger.getLogger(HealthDemo.class.getName());

    public static void main(String[] args) {
        PartitionLog p0 = new PartitionLog(0);
        p0.produce(new Message(0, "SAV2001", new BigDecimal("1200")));
        p0.produce(new Message(1, "CUR3001", new BigDecimal("5000")));
        p0.produce(new Message(2, "SAV2001", null));            // poison
        p0.produce(new Message(3, "CUR3001", new BigDecimal("800")));

        ConsumerGroup group = new ConsumerGroup(3);
        group.addConsumer("consumer-A", List.of(p0));

        log.info("=== POLL (process, measure lag, DLQ poison) ===");
        group.poll(p0);
        log.info("DLQ size = " + group.dlqSize());

        log.info("=== Add a consumer → rebalance ===");
        group.addConsumer("consumer-B", List.of(p0));
    }
}
